import Foundation
import Testing
@testable import VistaCore

/// Synthetic, range-generated bytes only. No full-file fixture, SMB or device work.
@Suite(.serialized)
@MainActor struct PlaybackRing128CapacityTests {
    // Virtual 256 MiB source; materializes only each requested <=2 MiB range.
    @MainActor final class Source: PlaybackCacheSource {
        var reads: [Range<UInt64>] = [], speculative: [Range<UInt64>] = []
        var blockedPrefetch: Set<Int> = [], blockedDemand: Range<UInt64>?
        var gate: CheckedContinuation<Void, Never>?
        var token: UInt64? = 1, stopped = false
        var outstanding = 0, maxOutstanding = 0, maxGeneratedBytes = 0
        var largestSegmentCount = 0
        var isPlaybackRecovering: Bool { false }
        var recoveryActiveStartedAt: TimeInterval? { nil }
        var recoveryActiveElapsed: TimeInterval { 0 }
        func playbackCacheEpoch() throws -> UInt64? { try Task.checkCancellation(); return stopped ? nil : token }
        func fileSize(for file: MediaFile) async throws -> UInt64 { 256 * 1_048_576 }
        static func data(_ range: Range<UInt64>) -> Data { PlaybackSharedRingTests.Source.data(range) }
        func produce(_ range: Range<UInt64>) -> Data {
            maxGeneratedBytes = max(maxGeneratedBytes, range.count)
            return Self.data(range)
        }
        func read(_ file: MediaFile, range: Range<UInt64>) async throws -> Data {
            reads.append(range); outstanding += 1; maxOutstanding = max(maxOutstanding, outstanding)
            defer { outstanding -= 1 }
            if blockedDemand == range { await withCheckedContinuation { gate = $0 } }
            try Task.checkCancellation()
            return produce(range)
        }
        func readForPrefetch(_ file: MediaFile, range: Range<UInt64>) async throws -> Data {
            speculative.append(range); outstanding += 1; maxOutstanding = max(maxOutstanding, outstanding)
            defer { outstanding -= 1 }
            if blockedPrefetch.contains(speculative.count) { await withCheckedContinuation { gate = $0 } }
            return produce(range)
        }
        func readCompletingCachedSegments(_ file: MediaFile, range: Range<UInt64>, segments: [PlaybackCachedSegment], epoch: UInt64) async throws -> PlaybackCachedReadResult {
            largestSegmentCount = max(largestSegmentCount, segments.count)
            guard epoch == token else { return .init(data: try await read(file, range: range), usedCachedBytes: 0) }
            var cursor = range.lowerBound, result = Data(capacity: range.count), used = 0
            for segment in segments {
                if cursor < segment.range.lowerBound { result.append(try await read(file, range: cursor..<segment.range.lowerBound)) }
                result.append(segment.data); used += segment.data.count; cursor = segment.range.upperBound
            }
            if cursor < range.upperBound { result.append(try await read(file, range: cursor..<range.upperBound)) }
            return .init(data: result, usedCachedBytes: used)
        }
        func release() { let saved = gate; gate = nil; saved?.resume() }
        func setPlaybackSceneActive(_ active: Bool) { if !active { token = nil } }
        func cancelPlayback() { stopped = true }
        func awaitPlaybackCleanup() async throws {}
    }
    private let file = try! MediaFile(components: ["generated-ring128.mp4"])
    private let mib = 1_048_576

    private func until(_ condition: @MainActor () -> Bool) async throws {
        let deadline = ContinuousClock.now.advanced(by: .seconds(3))
        while !condition(), ContinuousClock.now < deadline { await Task.yield() }
        try #require(condition(), "Synthetic 128 MiB gate did not reach expected state")
    }
    private func conserved(_ source: PlaybackPrefetchSource) {
        let m = source.metrics
        #expect(m.speculativeBytes == m.hitBytes + m.joinedBytes + m.discardedBytes + m.retiredSpeculativeBytes + UInt64(m.residentBytes))
        #expect(m.diagnostics.discardedBytes == m.discardedBytes)
    }
    private func fill(_ source: PlaybackPrefetchSource) async throws {
        source.setPrefetchEnabled(true)
        _ = try await source.read(file, range: 0..<UInt64(2 * mib))
        source.setPrefetchEnabled(false, reason: .pause)
        for start in stride(from: 2 * mib, to: 128 * mib, by: 2 * mib) {
            _ = try await source.read(file, range: UInt64(start)..<UInt64(start + 2 * mib))
        }
        #expect(source.metrics.historyBytes == 128 * mib && source.metrics.storageAllocatedBytes == 128 * mib)
    }

    @Test func explicitOneTwentyEightMiBBaselineKeepsForwardBudget() {
        let config = PlaybackPrefetchSource.Configuration(totalCapacityBytes: 128 * mib)
        #expect(config.totalCapacityBytes == 128 * mib && config.historyCapacityBytes == 128 * mib)
        #expect(config.capacityBytes == 4 * mib && config.chunkBytes == 2 * mib)
        #expect(MediaReadPlan.maximumChunkBytes == UInt64(2 * mib))
        let baseline = PlaybackPrefetchSource.Configuration(totalCapacityBytes: 96 * mib)
        #expect(baseline.totalCapacityBytes == 96 * mib)
        #expect(baseline.capacityBytes == config.capacityBytes && baseline.chunkBytes == config.chunkBytes)
        let legacy = PlaybackPrefetchSource.Configuration(capacityBytes: 4 * mib, chunkBytes: 2 * mib,
            historyCapacityBytes: 124 * mib)
        #expect(legacy.totalCapacityBytes == config.totalCapacityBytes && legacy.historyCapacityBytes == 124 * mib)
        #expect(legacy.capacityBytes == config.capacityBytes && legacy.chunkBytes == config.chunkBytes)
    }

    /// Run alone in a fresh process when comparing its physical footprint with the
    /// explicit 96 MiB baseline. Normal suite execution is correctness evidence only.
    @Test func fullOneTwentyEightMiBHistoryWrapsAndRetainsBeyondNinetySixMiB() async throws {
        let base = Source(), source = PlaybackPrefetchSource(file: file, source: base, configuration: .init(totalCapacityBytes: 128 * mib))
        var observations: [[String: Any]] = []
        func observe(_ stage: String) {
            let m = source.metrics
            observations.append(["stage": stage,
                "processPhysFootprintBytes": PlaybackSharedRingTests.footprint() as Any? ?? NSNull(),
                "ringAllocatedBytes": m.storageAllocatedBytes, "cacheAndReservationBytes": m.totalCacheBytes,
                "historyBytes": m.historyBytes, "readyBytes": m.residentBytes,
                "reservationBytes": m.inFlightReservedBytes, "snapshotBytes": m.demandSnapshotBytes,
                "ringWrittenBytes": m.storageWrittenBytes])
        }
        observe("before")
        source.setPrefetchEnabled(true)
        _ = try await source.read(file, range: 0..<UInt64(2 * mib))
        let saved = try await source.read(file, range: 0..<UInt64(2 * mib))
        #expect(base.reads.count == 1 && source.metrics.historyHitBytes == 2 * mib)
        source.setPrefetchEnabled(false, reason: .pause)
        for start in stride(from: 2 * mib, to: 128 * mib, by: 2 * mib) {
            _ = try await source.read(file, range: UInt64(start)..<UInt64(start + 2 * mib))
        }
        #expect(source.metrics.historyBytes == 128 * mib && source.metrics.totalCacheBytes == 128 * mib)
        #expect(source.metrics.storageWrittenBytes == 128 * mib)
        observe("filled128MiB")
        _ = try await source.fileSize(for: file)
        base.blockedPrefetch = [1, 2]
        source.setPrefetchEnabled(true)
        _ = try await source.read(file, range: UInt64(128 * mib)..<UInt64(130 * mib))
        try await until { base.gate != nil }
        #expect(base.speculative == [UInt64(130 * mib)..<UInt64(132 * mib)])
        #expect(source.metrics.historyBytes == 128 * mib && source.metrics.inFlightReservedBytes == 2 * mib)
        #expect(source.metrics.totalCacheBytes == 130 * mib)
        observe("firstReserved")
        base.release()
        try await until { base.speculative.count == 2 && base.gate != nil }
        #expect(source.metrics.historyBytes == 126 * mib && source.metrics.residentBytes == 2 * mib)
        #expect(source.metrics.totalCacheBytes == 130 * mib && source.metrics.inFlightReservedBytes == 2 * mib)
        observe("secondReserved")
        source.setPrefetchEnabled(false, reason: .pause)
        base.release()
        try await until { source.metrics.residentBytes == 4 * mib }
        #expect(source.metrics.storageWrittenBytes == 134 * mib && source.metrics.historyBytes == 124 * mib)
        source.setPrefetchEnabled(true)
        try await Task.sleep(for: .milliseconds(20)) // Idle admission cannot issue a third 2 MiB read.
        #expect(base.speculative.count == 2 && source.metrics.residentBytes == 4 * mib)
        #expect(source.metrics.inFlightReservedBytes == 0)
        source.setPrefetchEnabled(false, reason: .pause)
        let reads = base.reads.count
        // 100.0625 MiB and 122 MiB behind the history end exceed the old 96 MiB window.
        let backwards = [UInt64(30 * mib - 65_536)..<UInt64(32 * mib - 65_536),
                         UInt64(8 * mib)..<UInt64(10 * mib),
                         UInt64(127 * mib)..<UInt64(129 * mib)] // Straddles the physical wrap.
        for range in backwards { #expect(try await source.read(file, range: range) == Source.data(range)) }
        #expect(base.reads.count == reads && source.metrics.storageWrittenBytes == 134 * mib)
        base.blockedDemand = UInt64(5 * mib)..<UInt64(6 * mib)
        let gap = Task { try await source.read(file, range: UInt64(5 * mib)..<UInt64(7 * mib)) }
        try await until { base.gate != nil }
        #expect(source.metrics.demandSnapshotBytes == mib)
        observe("partialGapSuspended")
        base.blockedDemand = nil; base.release()
        #expect(try await gap.value == Source.data(UInt64(5 * mib)..<UInt64(7 * mib)))
        #expect(source.metrics.maxTotalCacheBytes == 130 * mib && source.metrics.maxStorageAllocatedBytes == 128 * mib)
        #expect(source.metrics.maxDemandSnapshotBytes == 2 * mib && base.maxGeneratedBytes == 2 * mib)
        #expect(base.maxOutstanding == 1 && base.speculative == [UInt64(130 * mib)..<UInt64(132 * mib), UInt64(132 * mib)..<UInt64(134 * mib)])
        #expect(base.reads.allSatisfy { $0.count <= 2 * mib })
        #expect(saved == Source.data(0..<UInt64(2 * mib)))
        observe("wrappedAndFilledGap")
        let outside = UInt64(2 * mib)..<UInt64(4 * mib)
        let beforeOutside = base.reads.count
        #expect(try await source.read(file, range: outside) == Source.data(outside))
        #expect(base.reads.count == beforeOutside + 1 && base.reads.last == outside)
        #expect(source.metrics.maxCacheMetadataEntries <= PlaybackPrefetchSource.Metrics.cacheMetadataEntryLimit)
        conserved(source)
        try await source.awaitPlaybackCleanup()
        #expect(source.metrics.storageAllocatedBytes == 0 && source.metrics.totalCacheBytes == 0)
        #expect(saved == Source.data(0..<UInt64(2 * mib)))
        observe("cleaned")
        let summary: [String: Any] = ["scope": "one synthetic wrapper in test process, not Vista or AVPlayer", "observations": observations,
            "externallyHeldReplyBytes": saved.count, "maximumSnapshotPayloadBytes": source.metrics.maxDemandSnapshotBytes,
            "maximumGeneratedSourcePayloadBytes": base.maxGeneratedBytes, "maximumRingPayloadBytes": source.metrics.maxStorageAllocatedBytes,
            "maximumArenaPlusReadReservationBytes": source.metrics.maxTotalCacheBytes,
            "maximumMetadataEntries": source.metrics.maxCacheMetadataEntries,
            "maximumRetainedMetadataAllocationBytes": source.metrics.maxCacheMetadataAllocatedBytes]
        print("RING128_MEMORY_JSON " + String(decoding: try JSONSerialization.data(withJSONObject: summary, options: [.sortedKeys]), as: UTF8.self))
    }

    @Test(arguments: ["memory", "stop", "epoch", "inactive", "seek"])
    func fullArenaRejectsLatePrefetchAcrossSafetyBoundaries(boundary: String) async throws {
        let base = Source(), source = PlaybackPrefetchSource(file: file, source: base, configuration: .init(totalCapacityBytes: 128 * mib))
        try await fill(source)
        _ = try await source.fileSize(for: file)
        base.blockedPrefetch = [1]
        source.setPrefetchEnabled(true)
        _ = try await source.read(file, range: UInt64(128 * mib)..<UInt64(130 * mib))
        try await until { base.gate != nil }
        #expect(source.metrics.validCacheBytes == 128 * mib && source.metrics.inFlightReservedBytes == 2 * mib)
        switch boundary {
        case "seek": source.invalidatePrefetch(reason: .seek)
        case "memory": source.handleMemoryPressure()
        case "stop": source.cancelPlayback()
        case "epoch": base.token = 2
        default: source.setPlaybackSceneActive(false) // This fixture cannot revalidate retained bytes.
        }
        if boundary == "seek" {
            #expect(source.metrics.storageAllocatedBytes == 128 * mib && source.metrics.historyBytes == 128 * mib)
            #expect(source.metrics.inFlightReservedBytes == 2 * mib)
        } else if boundary != "epoch" { #expect(source.metrics.storageAllocatedBytes == 0) }
        base.release()
        try await until { source.metrics.inFlightReservedBytes == 0 }
        let retainedBytes = boundary == "seek" ? 128 * mib : 0
        #expect(source.metrics.storageAllocatedBytes == retainedBytes && source.metrics.totalCacheBytes == retainedBytes)
        #expect(source.metrics.historyBytes == retainedBytes && source.metrics.residentBytes == 0)
        #expect(source.metrics.discardedBytes == UInt64(2 * mib))
        #expect(base.speculative.count == 1 && base.maxOutstanding == 1)
        if boundary == "memory" {
            source.setPlaybackSceneActive(false); source.setPlaybackSceneActive(true)
            base.token = 1
            source.setPrefetchEnabled(true)
            for start in [8, 10, 12] {
                let range = UInt64(start * mib)..<UInt64((start + 2) * mib)
                #expect(try await source.read(file, range: range) == Source.data(range))
                #expect(source.metrics.storageAllocatedBytes == 0 && source.metrics.totalCacheBytes == 0)
            }
            #expect(base.speculative.count == 1)
            // Only constructing a new wrapper restores cache admission after pressure.
            let replacement = PlaybackPrefetchSource(file: file, source: Source(), configuration: .init(totalCapacityBytes: 128 * mib))
            replacement.setPrefetchEnabled(true)
            _ = try await replacement.read(file, range: 0..<UInt64(2 * mib))
            #expect(replacement.metrics.storageAllocatedBytes == 128 * mib && replacement.metrics.historyBytes == 2 * mib)
            try await replacement.awaitPlaybackCleanup()
        } else if boundary == "seek" {
            let reads = base.reads.count
            let range = UInt64(8 * mib)..<UInt64(10 * mib)
            #expect(try await source.read(file, range: range) == Source.data(range))
            #expect(base.reads.count == reads && source.metrics.storageWrittenBytes == 130 * mib)
        } else if boundary == "stop" {
            let reads = base.reads.count
            do { _ = try await source.read(file, range: 0..<UInt64(2 * mib)); Issue.record("Read after stop") }
            catch { #expect(error is CancellationError) }
            #expect(base.reads.count == reads)
        }
        conserved(source)
        try await source.awaitPlaybackCleanup()
        #expect(source.metrics.storageAllocatedBytes == 0 && source.metrics.cacheMetadataEntries == 0)
    }

    @MainActor private final class RevalidatingHarness {
        let file: MediaFile
        let base = Source()
        var stats = 0, creates = 0
        var metadataGate: CheckedContinuation<Void, Never>?
        var blockMetadata = false
        var identity = PlaybackSourceIdentity(size: 256 * 1_048_576,
            modificationDate: Date(timeIntervalSince1970: 100), creationDate: Date(timeIntervalSince1970: 50))
        init(file: MediaFile) { self.file = file }
        lazy var source = PlaybackRecoveringSource(file: file, initial: base, metadata: { _, _ in
            self.stats += 1
            if self.blockMetadata { await withCheckedContinuation { self.metadataGate = $0 } }
            return self.identity
        }, makeFresh: { self.creates += 1; return Source() }, retire: { _ in },
        shouldRecover: { _ in false }, isCurrent: { true }, diagnostics: nil)
        func release() { let gate = metadataGate; metadataGate = nil; gate?.resume() }
    }

    @Test(arguments: [false, true])
    func fullArenaBackgroundRequiresIdentityValidationBeforeBackread(identityChanged: Bool) async throws {
        let h = RevalidatingHarness(file: file)
        let source = PlaybackPrefetchSource(file: file, source: h.source, configuration: .init(totalCapacityBytes: 128 * mib))
        _ = try await source.fileSize(for: file)
        try await fill(source)
        let reads = h.base.reads.count
        source.setPlaybackSceneActive(false)
        #expect(source.metrics.cacheQuarantined && source.metrics.validCacheBytes == 128 * mib)
        #expect(source.metrics.storageAllocatedBytes == 128 * mib)
        source.setPlaybackSceneActive(true)
        h.blockMetadata = true
        let range = UInt64(8 * mib)..<UInt64(10 * mib)
        let backread = Task { try await source.read(file, range: range) }
        try await until { h.metadataGate != nil }
        #expect(source.metrics.cacheQuarantined && source.metrics.historyHitBytes == 0)
        #expect(source.metrics.demandSnapshotBytes == 2 * mib && h.base.reads.count == reads)
        if identityChanged {
            h.identity = .init(size: 256 * UInt64(mib), modificationDate: Date(timeIntervalSince1970: 200),
                               creationDate: Date(timeIntervalSince1970: 50))
        }
        h.blockMetadata = false; h.release()
        if identityChanged {
            do { _ = try await backread.value; Issue.record("Published bytes after identity change") }
            catch { #expect(error as? PlaybackSourceRecoveryError == .identityChanged) }
            #expect(source.metrics.historyHitBytes == 0 && source.metrics.storageAllocatedBytes == 0)
        } else {
            #expect(try await backread.value == Source.data(range))
            #expect(source.metrics.historyHitBytes == 2 * mib && source.metrics.validCacheBytes == 128 * mib)
            #expect(!source.metrics.cacheQuarantined && source.metrics.diagnostics.quarantineValidatedCount == 1)
        }
        #expect(h.stats == 2 && h.base.reads.count == reads && h.creates == 0)
        #expect(h.base.maxOutstanding == 1)
        conserved(source)
        try await source.awaitPlaybackCleanup()
        #expect(source.metrics.storageAllocatedBytes == 0 && source.metrics.totalCacheBytes == 0)
    }
}
